beforeExample:
import java.util.HashMap;
import java.util.Map;
import java.util.List;

class MyClass {
    void myMethod() {
        Map<String, String> map1 = new HashMap<String, String>();
        HashMap<Integer, List<String>> map2 = new HashMap<Integer, List<String>>();
    }
}

afterExample:
import java.util.HashMap;
import java.util.Map;
import java.util.List;

class MyClass {
    void myMethod() {
        Map<String, String> map1 = new HashMap<>();
        HashMap<Integer, List<String>> map2 = new HashMap<>();
    }
}

negativeExample:
import java.util.HashMap;
import java.util.Map;

class MyClass {
    void myMethod() {
        Map<String, String> map1 = new HashMap<>(); // Already uses diamond
        Map<String, String> map2 = new HashMap<String, String>() {}; // Anonymous class, diamond not applicable
    }
}
